<meta name="description" content="Procedural Asteroid Defense Command — an assetless, single-file canvas arcade defense game with procedural audio."/>
<title>Procedural Asteroid Defense Command</title>
<style>
:root{
  --bg:#08080a;
  --panel:rgba(17,17,22,.66);
  --border:rgba(255,255,255,.08);
  --border-2:rgba(255,255,255,.16);
  --text:#f5f6f8;
  --muted:#8b8b96;
  --muted-2:#585862;
  --accent:#7c8cff;
  --accent-2:#22d3ee;
  --danger:#ff5470;
  --warn:#ffb26b;
  --font:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Inter,Helvetica,Arial,sans-serif;
  --mono:ui-monospace,"SF Mono","Cascadia Code","JetBrains Mono",Menlo,Consolas,monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  background:var(--bg);color:var(--text);font-family:var(--font);
  overflow:hidden;user-select:none;-webkit-user-select:none;
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
}
#stage{position:fixed;inset:0}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:crosshair}
body[data-state="menu"] canvas,body[data-state="over"] canvas{cursor:default}
.hidden{display:none!important}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}

/* ---------- HUD ---------- */
#hud{
  position:absolute;top:0;left:0;right:0;z-index:5;
  display:flex;justify-content:space-between;align-items:flex-start;
  padding:14px 16px;pointer-events:none;transition:opacity .35s ease;
}
body[data-state="menu"] #hud{opacity:.35}
.hud-cluster{display:flex;align-items:center;gap:18px}
.brand{display:flex;align-items:center;gap:8px;font:600 10px var(--mono);letter-spacing:.26em;color:var(--muted);white-space:nowrap}
.brand i{width:7px;height:7px;border-radius:2px;background:linear-gradient(135deg,var(--accent),var(--accent-2));box-shadow:0 0 10px rgba(124,140,255,.8)}
.score-block{display:flex;align-items:baseline;gap:8px}
.label{font:600 9px var(--mono);letter-spacing:.24em;color:var(--muted-2)}
.value{font-size:15px;font-weight:700}
.score-block .value{font-size:17px}
.combo{font-size:11.5px;font-weight:700;color:var(--accent-2);opacity:0;transform:translateY(2px);transition:opacity .2s,transform .2s;text-shadow:0 0 14px rgba(34,211,238,.7)}
.combo.on{opacity:1;transform:none}
.stat{display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.shield-block{display:flex;flex-direction:column;align-items:flex-end;gap:5px}
.bar{width:110px;height:4px;border-radius:99px;background:rgba(255,255,255,.07);overflow:hidden}
#hudShield{height:100%;width:100%;border-radius:99px;background:linear-gradient(90deg,var(--accent-2),var(--accent));transition:width .18s ease,background .3s}
#hudShield.low{background:linear-gradient(90deg,var(--danger),var(--warn))}
.hud-btns{display:flex;gap:8px;pointer-events:auto}
.icon-btn{
  width:34px;height:34px;display:grid;place-items:center;
  background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:9px;
  color:var(--muted);cursor:pointer;
  transition:color .15s,border-color .15s,background .15s,transform .1s,opacity .2s;
}
.icon-btn:hover{color:var(--text);border-color:var(--border-2);background:rgba(255,255,255,.06)}
.icon-btn:active{transform:scale(.94)}
.icon-btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
body[data-state="menu"] #btnPause,body[data-state="over"] #btnPause{opacity:.3;pointer-events:none}
#btnMute .ic-off{display:none}
#btnMute.muted .ic-on{display:none}
#btnMute.muted .ic-off{display:block}
#btnMute.muted{color:var(--danger)}
#btnPause .ic-play{display:none}
body[data-state="paused"] #btnPause .ic-pause{display:none}
body[data-state="paused"] #btnPause .ic-play{display:block}

/* ---------- OVERLAYS ---------- */
#overlays{position:absolute;inset:0;z-index:10;display:grid;place-items:center;padding:20px;pointer-events:none;overflow:auto}
.overlay{display:flex;justify-content:center;width:100%}
.panel{
  pointer-events:auto;width:min(470px,100%);
  background:var(--panel);border:1px solid var(--border);border-radius:16px;
  padding:32px 32px 28px;
  backdrop-filter:blur(20px) saturate(1.4);-webkit-backdrop-filter:blur(20px) saturate(1.4);
  box-shadow:0 30px 90px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.05);
  animation:panelIn .42s cubic-bezier(.16,1,.3,1) both;
}
@keyframes panelIn{from{opacity:0;transform:translateY(16px) scale(.98)}to{opacity:1;transform:none}}
.eyebrow{font:600 10px var(--mono);letter-spacing:.3em;color:var(--accent);margin-bottom:16px}
.eyebrow.danger{color:var(--danger)}
h1{font-size:clamp(25px,5.5vw,33px);line-height:1.1;font-weight:800;letter-spacing:-.015em;margin-bottom:14px}
h1 .grad{background:linear-gradient(92deg,var(--accent) 20%,var(--accent-2) 80%);-webkit-background-clip:text;background-clip:text;color:transparent}
h2{font-size:clamp(22px,4.5vw,28px);font-weight:800;letter-spacing:-.01em;margin-bottom:16px}
.lede{font-size:13.5px;line-height:1.7;color:var(--muted);margin-bottom:22px}
.keys{display:flex;flex-direction:column;gap:10px;margin-bottom:26px;font-size:12px;color:var(--muted)}
.keys em{font-style:normal;color:var(--muted-2);letter-spacing:.1em;text-transform:uppercase;font-size:9.5px;margin-left:5px}
.touch-line{font-size:9.5px;color:var(--muted-2);letter-spacing:.16em;text-transform:uppercase;margin-top:2px}
.key{display:inline-block;font:600 10px var(--mono);letter-spacing:.05em;color:var(--text);background:rgba(255,255,255,.05);border:1px solid var(--border-2);border-bottom-width:2px;border-radius:6px;padding:4px 7px;margin:0 5px 0 0;vertical-align:1px}
.btn{
  font:600 11.5px var(--mono);letter-spacing:.16em;padding:13px 22px;
  border-radius:10px;border:1px solid var(--border-2);
  background:rgba(255,255,255,.03);color:var(--text);cursor:pointer;
  transition:transform .12s ease,box-shadow .2s ease,border-color .2s,background .2s;
}
.btn:hover{transform:translateY(-1px);border-color:rgba(255,255,255,.32);background:rgba(255,255,255,.06)}
.btn:active{transform:translateY(0) scale(.99)}
.btn:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.btn.primary{
  border-color:rgba(124,140,255,.55);color:#fff;
  background:linear-gradient(180deg,rgba(124,140,255,.18),rgba(124,140,255,.04));
  box-shadow:0 0 28px rgba(124,140,255,.2),inset 0 0 14px rgba(124,140,255,.07);
}
.btn.primary:hover{box-shadow:0 0 40px rgba(124,140,255,.34),inset 0 0 18px rgba(124,140,255,.12);border-color:rgba(124,140,255,.8)}
.row{display:flex;gap:10px;flex-wrap:wrap}
.best{margin-top:20px;font:600 10px var(--mono);letter-spacing:.24em;color:var(--muted-2)}
.best b{color:var(--muted);font-weight:600;margin-left:8px}
.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:8px}
.stat-cell{background:rgba(255,255,255,.028);border:1px solid var(--border);border-radius:10px;padding:12px 12px 10px;display:flex;flex-direction:column;gap:7px}
.stat-cell .big{font-size:18px;font-weight:700}
.badge{margin:6px 0 18px;width:max-content;font:700 10px var(--mono);letter-spacing:.24em;color:#0b0b10;background:linear-gradient(90deg,var(--accent),var(--accent-2));padding:7px 13px;border-radius:99px;box-shadow:0 0 26px rgba(124,140,255,.45)}
#hint{
  position:absolute;bottom:11px;left:0;right:0;z-index:4;text-align:center;
  font:500 10px var(--mono);letter-spacing:.18em;color:var(--muted-2);
  pointer-events:none;transition:opacity .4s;
}
body[data-state="menu"] #hint{opacity:0}

/* ---------- RESPONSIVE ---------- */
@media (max-width:560px){
  #hud{padding:10px 12px}
  .brand{display:none}
  .hud-cluster{gap:12px}
  .score-block .value{font-size:15px}
  .bar{width:84px}
  .panel{padding:24px 20px 22px}
  #hint{letter-spacing:.12em}
}
@media (max-height:480px){
  .panel{padding:18px 20px 16px}
  h1{margin-bottom:10px;font-size:22px}
  h2{margin-bottom:10px;font-size:20px}
  .lede{margin-bottom:14px;font-size:12.5px}
  .keys{margin-bottom:16px;gap:7px}
  .best{margin-top:12px}
}
@media (prefers-reduced-motion:reduce){
  .panel{animation:none}
}
</style>
