<script>
(() => {
'use strict';

/* ================================================================
   CONSTANTS & UTILITIES
================================================================ */
const TAU = Math.PI * 2;
const SANS = 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Inter, Arial, sans-serif';
const MONO = 'ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace';
const STEP = 1000 / 60;                       // fixed physics step (ms)
const S = { MENU: 0, PLAYING: 1, PAUSED: 2, OVER: 3 };
const STATE_NAMES = ['menu', 'playing', 'paused', 'over'];

const rand  = (a, b) => (b === undefined ? Math.random() * a : a + Math.random() * (b - a));
const irand = (a, b) => (a + Math.random() * (b - a + 1)) | 0;
const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp  = (a, b, t) => a + (b - a) * t;
const fmt   = (n) => n.toLocaleString('en-US');

/* ================================================================
   DOM BINDINGS
================================================================ */
const $ = (id) => document.getElementById(id);
const canvas = $('game');
const ctx = canvas && canvas.getContext ? canvas.getContext('2d', { alpha: false }) : null;
const elScore = $('hudScore'), elWave = $('hudWave'), elShield = $('hudShield'), elCombo = $('hudCombo');
const elMenuBest = $('menuBest'), elFinalScore = $('finalScore'), elFinalWave = $('finalWave'), elFinalBest = $('finalBest');
const elBadge = $('recordBadge'), elHint = $('hint');
const ovMenu = $('ovMenu'), ovPause = $('ovPause'), ovOver = $('ovOver');
const btnStart = $('btnStart'), btnRetry = $('btnRetry'), btnResume = $('btnResume');
const btnQuit = $('btnQuit'), btnMenu2 = $('btnMenu2'), btnPause = $('btnPause'), btnMute = $('btnMute');

if (!ctx) {
  elHint.textContent = 'CANVAS 2D UNSUPPORTED — PLEASE UPGRADE YOUR BROWSER';
  return;
}

/* ================================================================
   GAME STATE
================================================================ */
let state = S.MENU;
let W = 0, H = 0, dpr = 1;
let score = 0, best = 0, wave = 1, waveTimer = 0, shield = 100;
let combo = 0, comboT = 0, mult = 1;
let shake = 0, flashRed = 0, flashWhite = 0, dying = 0;
let spawnTimer = 1.2, elapsed = 0, tGlobal = 0, ambientTimer = 1, fireCd = 0, engineAcc = 0;
let newRecord = false, overAt = 0, muted = false;
let acc = 0, last = performance.now();

try { best = parseInt(localStorage.getItem('adc_best'), 10) || 0; } catch (e) { best = 0; }

const player = { x: 0, y: 0, vx: 0, alive: true, inv: 0 };
const keys = { left: false, right: false, fire: false };
let pointerDown = false, pointerX = 0;
const ann = { text: '', sub: '', t: 1, dur: 0 };

/* ================================================================
   AUDIO — procedural SFX + generative music (Web Audio API)
================================================================ */
const A = {
  ctx: null, sfx: null, music: null, noise: null, master: null,
  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      const comp = this.ctx.createDynamicsCompressor();
      comp.threshold.value = -18; comp.knee.value = 24; comp.ratio.value = 8;
      comp.attack.value = 0.004; comp.release.value = 0.18;
      this.master = this.ctx.createGain();
      this.master.gain.value = muted ? 0 : 0.85;
      this.master.connect(comp);
      comp.connect(this.ctx.destination);
      this.sfx = this.ctx.createGain();
      this.sfx.gain.value = 0.9;
      this.sfx.connect(this.master);
      this.music = this.ctx.createGain();
      this.music.gain.value = 0.0001;
      this.music.connect(this.master);
      const len = Math.floor(this.ctx.sampleRate);
      this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = this.noise.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    } catch (e) { this.ctx = null; }
  },
  setMuted(m) {
    muted = m;
    if (this.ctx && this.master) {
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.setTargetAtTime(m ? 0 : 0.85, t, 0.05);
    }
  }
};

const SFX = {
  lastShot: 0,
  shoot() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    if (t - this.lastShot < 0.045) return;
    this.lastShot = t;
    const o = c.createOscillator(), f = c.createBiquadFilter(), g = c.createGain();
    o.type = 'sawtooth';
    o.frequency.setValueAtTime(920, t);
    o.frequency.exponentialRampToValueAtTime(150, t + 0.085);
    f.type = 'lowpass';
    f.frequency.setValueAtTime(2800, t);
    f.frequency.exponentialRampToValueAtTime(500, t + 0.09);
    g.gain.setValueAtTime(0.075, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.095);
    o.connect(f); f.connect(g); g.connect(A.sfx);
    o.start(t); o.stop(t + 0.1);
  },
  tick() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const o = c.createOscillator(), g = c.createGain();
    o.type = 'triangle';
    o.frequency.setValueAtTime(1400, t);
    o.frequency.exponentialRampToValueAtTime(600, t + 0.03);
    g.gain.setValueAtTime(0.05, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.04);
    o.connect(g); g.connect(A.sfx);
    o.start(t); o.stop(t + 0.05);
  },
  explosion(size) {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const dur = 0.22 + size * 0.1;
    const src = c.createBufferSource();
    src.buffer = A.noise;
    src.playbackRate.value = 0.8 + Math.random() * 0.3;
    const f = c.createBiquadFilter();
    f.type = 'lowpass'; f.Q.value = 0.8;
    f.frequency.setValueAtTime(2400, t);
    f.frequency.exponentialRampToValueAtTime(90, t + dur);
    const g = c.createGain();
    g.gain.setValueAtTime(0.3 + size * 0.15, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(A.sfx);
    src.start(t); src.stop(t + dur + 0.05);
    const o = c.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(120, t);
    o.frequency.exponentialRampToValueAtTime(38, t + dur * 0.8);
    const og = c.createGain();
    og.gain.setValueAtTime(0.5, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + dur * 0.9);
    o.connect(og); og.connect(A.sfx);
    o.start(t); o.stop(t + dur);
  },
  shieldHit() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const src = c.createBufferSource();
    src.buffer = A.noise;
    const f = c.createBiquadFilter();
    f.type = 'bandpass'; f.Q.value = 1.2;
    f.frequency.setValueAtTime(420, t);
    f.frequency.exponentialRampToValueAtTime(120, t + 0.2);
    const g = c.createGain();
    g.gain.setValueAtTime(0.3, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    src.connect(f); f.connect(g); g.connect(A.sfx);
    src.start(t); src.stop(t + 0.25);
    const o = c.createOscillator();
    o.type = 'sine';
    o.frequency.setValueAtTime(160, t);
    o.frequency.exponentialRampToValueAtTime(50, t + 0.18);
    const og = c.createGain();
    og.gain.setValueAtTime(0.28, t);
    og.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
    o.connect(og); og.connect(A.sfx);
    o.start(t); o.stop(t + 0.22);
  },
  wave() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const notes = [[440, 0], [659.25, 0.11], [880, 0.22]];
    for (let i = 0; i < notes.length; i++) {
      const o = c.createOscillator(), g = c.createGain();
      o.type = 'triangle';
      o.frequency.value = notes[i][0];
      const d = notes[i][1];
      g.gain.setValueAtTime(0.0001, t + d);
      g.gain.exponentialRampToValueAtTime(0.14, t + d + 0.015);
      g.gain.exponentialRampToValueAtTime(0.0001, t + d + 0.3);
      o.connect(g); g.connect(A.sfx);
      o.start(t + d); o.stop(t + d + 0.32);
    }
  },
  gameOver() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const notes = [392, 311.13, 246.94, 155.56];
    for (let i = 0; i < notes.length; i++) {
      const d = i * 0.19;
      const o = c.createOscillator(), fl = c.createBiquadFilter(), g = c.createGain();
      o.type = 'sawtooth';
      o.frequency.value = notes[i];
      fl.type = 'lowpass';
      fl.frequency.setValueAtTime(1400, t + d);
      fl.frequency.exponentialRampToValueAtTime(300, t + d + 0.3);
      g.gain.setValueAtTime(0.16, t + d);
      g.gain.exponentialRampToValueAtTime(0.0001, t + d + 0.34);
      o.connect(fl); fl.connect(g); g.connect(A.sfx);
      o.start(t + d); o.stop(t + d + 0.36);
    }
    const src = c.createBufferSource();
    src.buffer = A.noise; src.loop = true;
    const f2 = c.createBiquadFilter();
    f2.type = 'lowpass';
    f2.frequency.setValueAtTime(220, t);
    f2.frequency.exponentialRampToValueAtTime(60, t + 1.2);
    const g2 = c.createGain();
    g2.gain.setValueAtTime(0.22, t);
    g2.gain.exponentialRampToValueAtTime(0.0001, t + 1.3);
    src.connect(f2); f2.connect(g2); g2.connect(A.sfx);
    src.start(t); src.stop(t + 1.35);
  },
  playerDown() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const o = c.createOscillator(), f = c.createBiquadFilter(), g = c.createGain();
    o.type = 'square';
    o.frequency.setValueAtTime(300, t);
    o.frequency.exponentialRampToValueAtTime(40, t + 0.7);
    f.type = 'lowpass';
    f.frequency.setValueAtTime(1200, t);
    f.frequency.exponentialRampToValueAtTime(120, t + 0.7);
    g.gain.setValueAtTime(0.22, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.75);
    o.connect(f); f.connect(g); g.connect(A.sfx);
    o.start(t); o.stop(t + 0.8);
  },
  click() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const o = c.createOscillator(), g = c.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(740, t);
    o.frequency.exponentialRampToValueAtTime(520, t + 0.05);
    g.gain.setValueAtTime(0.07, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
    o.connect(g); g.connect(A.sfx);
    o.start(t); o.stop(t + 0.07);
  },
  record() {
    const c = A.ctx; if (!c) return;
    const t = c.currentTime;
    const notes = [523.25, 659.25, 783.99, 1046.5];
    for (let i = 0; i < notes.length; i++) {
      const d = i * 0.09;
      const o = c.createOscillator(), g = c.createGain();
      o.type = 'triangle';
      o.frequency.value = notes[i];
      g.gain.setValueAtTime(0.0001, t + d);
      g.gain.exponentialRampToValueAtTime(0.13, t + d + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, t + d + 0.25);
      o.connect(g); g.connect(A.sfx);
      o.start(t + d); o.stop(t + d + 0.27);
    }
  }
};

const Music = {
  running: false, timer: 0, idx: 0, nextT: 0,
  bpm: 92,
  scale: [57, 60, 62, 64, 67, 69, 72],          // A minor pentatonic, A3..A5
  bass: [45, 41, 48, 43],                        // Am / F / C / G roots
  pat: [
    [0, -1, 3, -1, 5, -1, 3, -1, 4, -1, 3, -1, 2, -1, 0, -1],
    [0, -1, 2, -1, 4, -1, 2, -1, 5, -1, 4, -1, 4, -1, 2, -1],
    [0, -1, 3, -1, 5, -1, 7, -1, 6, -1, 5, -1, 4, -1, 3, -1],
    [2, -1, 4, -1, 5, -1, 4, -1, 3, -1, 2, -1, 1, -1, 0, -1]
  ],
  freq(m) { return 440 * Math.pow(2, (m - 69) / 12); },
  start() {
    if (!A.ctx || this.running) return;
    this.running = true;
    const t = A.ctx.currentTime;
    A.music.gain.cancelScheduledValues(t);
    A.music.gain.setTargetAtTime(0.5, t, 0.7);
    this.idx = 0;
    this.nextT = t + 0.08;
    this.timer = setInterval(() => this.sched(), 25);
  },
  stop() {
    if (!this.running) return;
    this.running = false;
    clearInterval(this.timer);
    this.timer = 0;
    if (A.ctx) {
      const t = A.ctx.currentTime;
      A.music.gain.cancelScheduledValues(t);
      A.music.gain.setTargetAtTime(0.0001, t, 0.35);
    }
  },
  sched() {
    const c = A.ctx;
    if (!c || !this.running) return;
    const s16 = 60 / this.bpm / 4;
    while (this.nextT < c.currentTime + 0.12) {
      this.note(this.idx, this.nextT);
      this.nextT += s16;
      this.idx = (this.idx + 1) & 63;
    }
  },
  note(i, t) {
    const bar = (i >> 4) & 3, st = i & 15;
    if (st === 0 || st === 4 || st === 8 || st === 12) this.bass(this.bass[bar], t, 0.2, 0.34);
    else if (st === 10) this.bass(this.bass[bar] + 3, t, 0.13, 0.2);
    const deg = this.pat[bar][st];
    if (deg >= 0) this.pluck(this.scale[deg], t);
    if ((st & 1) === 1) this.hat(t, (st % 4 === 3) ? 0.03 : 0.016);
  },
  bass(m, t, peak, dur) {
    const c = A.ctx;
    const o = c.createOscillator(), g = c.createGain();
    o.type = 'sine';
    o.frequency.value = this.freq(m);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(peak, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(A.music);
    o.start(t); o.stop(t + dur + 0.02);
  },
  pluck(m, t) {
    const c = A.ctx;
    const o = c.createOscillator(), f = c.createBiquadFilter(), g = c.createGain();
    o.type = 'triangle';
    o.frequency.value = this.freq(m);
    f.type = 'lowpass'; f.Q.value = 0.8;
    f.frequency.setValueAtTime(2400, t);
    f.frequency.exponentialRampToValueAtTime(700, t + 0.16);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.11, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
    o.connect(f); f.connect(g); g.connect(A.music);
    o.start(t); o.stop(t + 0.22);
  },
  hat(t, peak) {
    const c = A.ctx;
    const s = c.createBufferSource();
    s.buffer = A.noise;
    const f = c.createBiquadFilter();
    f.type = 'highpass';
    f.frequency.value = 6500;
    const g = c.createGain();
    g.gain.setValueAtTime(peak, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.035);
    s.connect(f); f.connect(g); g.connect(A.music);
    s.start(t, Math.random() * Math.max(0.01, A.noise.duration - 0.06));
    s.stop(t + 0.05);
  }
};

/* ================================================================
   PRE-RENDERED SPRITES (zero per-frame path work)
================================================================ */
function makeGlow(rgb) {
  const c = document.createElement('canvas');
  c.width = 64; c.height = 64;
  const g = c.getContext('2d');
  const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  gr.addColorStop(0, 'rgba(' + rgb + ',0.85)');
  gr.addColorStop(0.3, 'rgba(' + rgb + ',0.4)');
  gr.addColorStop(1, 'rgba(' + rgb + ',0)');
  g.fillStyle = gr;
  g.fillRect(0, 0, 64, 64);
  return c;
}
const GLOW = {
  ember: makeGlow('255,150,90'),
  flame: makeGlow('255,110,55'),
  spark: makeGlow('124,140,255'),
  cyan:  makeGlow('34,211,238'),
  white: makeGlow('235,240,255'),
  red:   makeGlow('255,84,112')
};

const bulletSpr = (() => {
  const c = document.createElement('canvas');
  c.width = 32; c.height = 32;
  const g = c.getContext('2d');
  const gr = g.createRadialGradient(16, 16, 0, 16, 16, 16);
  gr.addColorStop(0, 'rgba(255,255,255,1)');
  gr.addColorStop(0.25, 'rgba(200,210,255,0.9)');
  gr.addColorStop(0.55, 'rgba(124,140,255,0.45)');
  gr.addColorStop(1, 'rgba(124,140,255,0)');
  g.fillStyle = gr;
  g.fillRect(0, 0, 32, 32);
  return c;
})();

let bodyGrad = null, strokeGrad = null;
function buildShipGrads() {
  bodyGrad = ctx.createLinearGradient(0, -20, 0, 14);
  bodyGrad.addColorStop(0, '#232330');
  bodyGrad.addColorStop(0.55, '#15151c');
  bodyGrad.addColorStop(1, '#101016');
  strokeGrad = ctx.createLinearGradient(0, -20, 0, 14);
  strokeGrad.addColorStop(0, 'rgba(196,206,255,0.95)');
  strokeGrad.addColorStop(1, 'rgba(124,140,255,0.55)');
}

const AST_R = { 3: 36, 2: 21, 1: 13 };
function makeAsteroidSprite(r) {
  const pad = 4;
  const s = Math.ceil((r + pad) * 2);
  const c = document.createElement('canvas');
  c.width = s; c.height = s;
  const g = c.getContext('2d');
  g.translate(s / 2, s / 2);
  const n = irand(9, 12);
  g.beginPath();
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TAU;
    const rr = r * (0.74 + Math.random() * 0.4);
    const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
    if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
  }
  g.closePath();
  const gr = g.createRadialGradient(-r * 0.35, -r * 0.4, r * 0.1, 0, 0, r * 1.2);
  gr.addColorStop(0, '#2a2a34');
  gr.addColorStop(0.65, '#1a1a21');
  gr.addColorStop(1, '#111116');
  g.fillStyle = gr;
  g.fill();
  g.save();
  g.clip();
  g.fillStyle = 'rgba(0,0,0,0.38)';
  const nc = irand(2, 4);
  for (let i = 0; i < nc; i++) {
    g.beginPath();
    g.arc(rand(-r * 0.6, r * 0.6), rand(-r * 0.6, r * 0.6), r * rand(0.14, 0.3), 0, TAU);
    g.fill();
  }
  g.restore();
  g.strokeStyle = 'rgba(180,190,255,0.16)';
  g.lineWidth = 1.25;
  g.stroke();
  return { img: c, s: s };
}

/* ---------- environment layers ---------- */
let gridPattern = null, vignette = null;
const stars = [];

function rebuildGrid() {
  const c = document.createElement('canvas');
  const cell = 44;
  c.width = cell; c.height = cell;
  const g = c.getContext('2d');
  g.strokeStyle = 'rgba(255,255,255,0.04)';
  g.lineWidth = 1;
  g.beginPath();
  g.moveTo(0.5, 0); g.lineTo(0.5, cell);
  g.moveTo(0, 0.5); g.lineTo(cell, 0.5);
  g.stroke();
  gridPattern = ctx.createPattern(c, 'repeat');
}

function rebuildVignette() {
  const c = document.createElement('canvas');
  c.width = Math.max(2, Math.round(W / 2));
  c.height = Math.max(2, Math.round(H / 2));
  const g = c.getContext('2d');
  const R = Math.sqrt(W * W + H * H) / 4;
  const gr = g.createRadialGradient(c.width / 2, c.height / 2, R * 0.5, c.width / 2, c.height / 2, R);
  gr.addColorStop(0, 'rgba(0,0,0,0)');
  gr.addColorStop(1, 'rgba(0,0,0,0.55)');
  g.fillStyle = gr;
  g.fillRect(0, 0, c.width, c.height);
  vignette = c;
}

function rebuildStars() {
  stars.length = 0;
  const n = Math.round(clamp((W * H) / 9000, 60, 180));
  for (let i = 0; i < n; i++) {
    const big = Math.random() < 0.35;
    stars.push({
      x: Math.random() * W, y: Math.random() * H,
      s: big ? 1.7 : 1,
      v: big ? rand(16, 30) : rand(6, 13),
      base: big ? 0.5 : 0.24,
      tw: rand(0.5, 2.4), ph: rand(TAU)
    });
  }
}

/* ================================================================
   OBJECT POOLS (fixed capacity, zero allocation in hot paths)
================================================================ */
const AST_MAX = 90;
const asteroids = [];                       // swap-remove array

const BUL_MAX = 80;
const B = new Array(BUL_MAX);
for (let i = 0; i < BUL_MAX; i++) B[i] = { x: 0, y: 0, vx: 0, vy: 0, alive: false };

const P_MAX = 512;                          // power of two for fast mask
const P = new Array(P_MAX);
for (let i = 0; i < P_MAX; i++) P[i] = { x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1, sz: 1, drag: 2, grav: 0, spr: null };
let pCursor = 0;

const TXT = new Array(16);
for (let i = 0; i < TXT.length; i++) TXT[i] = { t: 0, life: 1, x: 0, y: 0, str: '', color: '#fff' };
let tCursor = 0;

function spawnP(x, y, vx, vy, life, sz, drag, grav, spr) {
  const p = P[pCursor];
  pCursor = (pCursor + 1) & (P_MAX - 1);
  p.x = x; p.y = y; p.vx = vx; p.vy = vy;
  p.life = life; p.max = life; p.sz = sz; p.drag = drag; p.grav = grav; p.spr = spr;
}
function burst(x, y, n, o) {
  for (let i = 0; i < n; i++) {
    const a = rand(TAU);
    const sp = rand(o.spd * 0.15, o.spd);
    const life = rand(o.life * 0.5, o.life);
    spawnP(x, y, Math.cos(a) * sp, Math.sin(a) * sp, life, rand(o.sz * 0.5, o.sz), o.drag, o.grav || 0, o.spr);
  }
}
function popup(x, y, str, color) {
  const t = TXT[tCursor];
  tCursor = (tCursor + 1) & 15;
  t.t = 0; t.life = rand(0.7, 0.95);
  t.x = clamp(x, 26, W - 26); t.y = clamp(y, 20, H - 20);
  t.str = str; t.color = color;
}

/* ================================================================
   ENTITY LOGIC
================================================================ */
function spawnAsteroid(size, x, y, vx, vy) {
  if (asteroids.length >= AST_MAX) return null;
  const r = AST_R[size] * rand(0.88, 1.12);
  const spr = makeAsteroidSprite(r);
  const a = {
    x: x, y: y, vx: vx, vy: vy, size: size, r: r,
    img: spr.img, imgS: spr.s,
    rot: rand(TAU),
    vr: rand(0.4, 1.4) * (Math.random() < 0.5 ? -1 : 1) * (size === 1 ? 1.5 : 1),
    hp: size === 3 ? 2 : 1,
    ambient: false
  };
  asteroids.push(a);
  return a;
}
function killAsteroid(i) {
  const lastIdx = asteroids.length - 1;
  asteroids[i] = asteroids[lastIdx];
  asteroids.pop();
}

function speedMult() { return Math.min(1 + (wave - 1) * 0.13, 2.4); }

function explode(x, y, size) {
  burst(x, y, 10 + size * 9, { spr: GLOW.ember, spd: 80 + size * 55, life: 0.7, sz: 1.2 + size * 0.5, drag: 3, grav: 30 });
  burst(x, y, 6 + size * 5, { spr: GLOW.white, spd: 60 + size * 45, life: 0.35, sz: 0.9 + size * 0.4, drag: 4.5, grav: 0 });
  if (size >= 2) burst(x, y, 8, { spr: GLOW.spark, spd: 80, life: 0.9, sz: 2, drag: 2.2, grav: 0 });
  SFX.explosion(size);
}

function splitAsteroid(a) {
  if (a.size <= 1) return;
  const cs = a.size - 1;
  const ang = rand(TAU);
  const dx = Math.cos(ang), dy = Math.sin(ang);
  const sp = 70 + cs * 40 + rand(0, 40);
  for (let k = 0; k < 2; k++) {
    const sgn = (k === 0) ? 1 : -1;
    const c = spawnAsteroid(cs,
      a.x + dx * a.r * 0.35 * sgn,
      a.y + dy * a.r * 0.35,
      a.vx * 0.4 + dx * sp * sgn,
      a.vy * 0.7 + dy * sp * 0.55 * sgn + 20);
    if (c) c.ambient = false;
  }
}

function hitAsteroid(i, hx, hy) {
  const a = asteroids[i];
  a.hp--;
  if (a.hp > 0) {
    burst(hx, hy, 6, { spr: GLOW.white, spd: 130, life: 0.3, sz: 1.5, drag: 4, grav: 0 });
    SFX.tick();
    return;
  }
  const pts = (a.size === 3 ? 10 : a.size === 2 ? 20 : 30) * mult;
  score += pts;
  combo++; comboT = 3;
  mult = Math.min(8, 1 + (combo >> 2));
  popup(a.x, a.y - a.r - 8, '+' + pts, mult > 1 ? 'rgba(34,211,238,0.95)' : 'rgba(235,240,255,0.95)');
  explode(a.x, a.y, a.size);
  splitAsteroid(a);
  shake = Math.min(shake + (a.size === 3 ? 4.5 : a.size === 2 ? 3 : 1.8), 20);
  killAsteroid(i);
}

function damagePerimeter(a) {
  if (shield <= 0 || dying > 0) return;
  shield -= a.size === 3 ? 15 : a.size === 2 ? 10 : 7;
  if (shield < 0) shield = 0;
  flashRed = Math.min(flashRed + 0.3, 1);
  shake = Math.min(shake + 4, 22);
  burst(a.x, H - 6, 12, { spr: GLOW.red, spd: 150, life: 0.45, sz: 2.2, drag: 3, grav: -120 });
  SFX.shieldHit();
  if (shield <= 0) startDeath();
}

function damagePlayer(dmg, x, y) {
  if (player.inv > 0 || dying > 0 || shield <= 0) return;
  shield -= dmg;
  if (shield < 0) shield = 0;
  player.inv = 1.15;
  flashRed = Math.min(flashRed + 0.45, 1);
  shake = Math.min(shake + 9, 24);
  burst(x, y, 16, { spr: GLOW.red, spd: 230, life: 0.5, sz: 2.4, drag: 3, grav: 0 });
  SFX.shieldHit();
  if (shield <= 0) startDeath();
}

function startDeath() {
  if (dying > 0) return;
  dying = 1.4;
  player.alive = false;
  flashWhite = 0.85;
  shake = 26;
  explode(player.x, player.y, 3);
  burst(player.x, player.y, 30, { spr: GLOW.white, spd: 330, life: 0.9, sz: 2.6, drag: 2.2, grav: 0 });
  burst(player.x, player.y, 20, { spr: GLOW.spark, spd: 250, life: 1.1, sz: 2.2, drag: 2, grav: 0 });
  SFX.playerDown();
}

function fireBullet(x, y, vx, vy) {
  for (let i = 0; i < BUL_MAX; i++) {
    const b = B[i];
    if (!b.alive) { b.alive = true; b.x = x; b.y = y; b.vx = vx; b.vy = vy; return; }
  }
}
function tryFire(dt) {
  fireCd -= dt;
  if ((keys.fire || pointerDown) && fireCd <= 0 && dying <= 0) {
    fireCd = 0.155;
    fireBullet(player.x - 8, player.y - 8, -16, -840);
    fireBullet(player.x + 8, player.y - 8, 16, -840);
    spawnP(player.x, player.y - 14, 0, -80, 0.1, 1.8, 4, 0, GLOW.white);
    SFX.shoot();
  }
}

function updatePlayer(dt) {
  if (!player.alive) return;
  if (pointerDown) {
    player.x += (pointerX - player.x) * (1 - Math.exp(-13 * dt));
  } else {
    const dir = (keys.left ? -1 : 0) + (keys.right ? 1 : 0);
    player.vx = lerp(player.vx, dir * 560, 1 - Math.exp(-11 * dt));
    player.x += player.vx * dt;
  }
  player.x = clamp(player.x, 20, W - 20);
  if (player.inv > 0) player.inv -= dt;
  engineAcc += dt;
  while (engineAcc > 0.024) {
    engineAcc -= 0.024;
    spawnP(player.x + rand(-3, 3), player.y + 15, rand(-14, 14), rand(90, 160),
      rand(0.16, 0.3), rand(1.1, 2), 3, 0,
      Math.random() < 0.55 ? GLOW.cyan : GLOW.spark);
  }
}

/* ================================================================
   SIMULATION — fixed timestep (1/60 s)
================================================================ */
function announce(text, sub) { ann.text = text; ann.sub = sub || ''; ann.t = 0; ann.dur = 2.4; }

function updateStars(dt) {
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i];
    s.y += s.v * dt;
    if (s.y > H + 2) { s.y = -2; s.x = Math.random() * W; }
  }
}
function updateParticles(dt) {
  for (let i = 0; i < P_MAX; i++) {
    const p = P[i];
    if (p.life <= 0) continue;
    p.life -= dt;
    if (p.life <= 0) { p.life = 0; continue; }
    p.x += p.vx * dt; p.y += p.vy * dt;
    p.vy += p.grav * dt;
    const dmp = 1 - Math.min(1, p.drag * dt);
    p.vx *= dmp; p.vy *= dmp;
  }
}
function updatePopups(dt) {
  for (let i = 0; i < TXT.length; i++) {
    const t = TXT[i];
    if (t.t < t.life) { t.t += dt; t.y -= 32 * dt; }
  }
}

function simPlaying(dt) {
  if (dying > 0) {
    dying -= dt;
    if (dying <= 0) { gameOver(); return; }
  } else {
    elapsed += dt;
    waveTimer += dt;
    const tw = 1 + Math.floor(waveTimer / 18);
    if (tw > wave) {
      wave = tw;
      shield = Math.min(100, shield + 12);
      SFX.wave();
      announce('WAVE ' + wave, 'THREAT LEVEL ' + Math.min(wave, 9) + ' · SHIELD +12');
    }
    if (comboT > 0) {
      comboT -= dt;
      if (comboT <= 0) { combo = 0; mult = 1; }
    }
    updatePlayer(dt);
    tryFire(dt);
    spawnTimer -= dt;
    const maxA = Math.min(4 + wave * 2, 26);
    if (spawnTimer <= 0 && asteroids.length < maxA) {
      spawnTimer = Math.max(0.24, 0.95 * Math.pow(0.9, wave - 1)) * rand(0.65, 1.4);
      const roll = Math.random();
      const size = roll < 0.68 ? 3 : (roll < 0.9 ? 2 : 1);
      const x = rand(30, Math.max(70, W - 30));
      const a = spawnAsteroid(size, x, -60,
        clamp((player.x - x) * 0.05 + rand(-55, 55), -150, 150),
        rand(60, 120) * speedMult());
      if (a) a.ambient = false;
    }
  }

  /* bullets */
  for (let i = 0; i < BUL_MAX; i++) {
    const b = B[i];
    if (!b.alive) continue;
    b.x += b.vx * dt; b.y += b.vy * dt;
    if (b.y < -24 || b.x < -24 || b.x > W + 24) b.alive = false;
  }
  /* bullet × asteroid (bounded O(B·A), swap-safe) */
  for (let bi = 0; bi < BUL_MAX; bi++) {
    const b = B[bi];
    if (!b.alive) continue;
    for (let ai = 0; ai < asteroids.length; ai++) {
      const a = asteroids[ai];
      const dx = a.x - b.x, dy = a.y - b.y, rr = a.r * 0.86 + 4;
      if (dx * dx + dy * dy < rr * rr) {
        b.alive = false;
        hitAsteroid(ai, b.x, b.y);
        break;
      }
    }
  }
  /* asteroid integration + collisions */
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx * dt; a.y += a.vy * dt; a.rot += a.vr * dt;
    if (a.x < a.r * 0.5) { a.x = a.r * 0.5; a.vx = Math.abs(a.vx) * 0.9; }
    else if (a.x > W - a.r * 0.5) { a.x = W - a.r * 0.5; a.vx = -Math.abs(a.vx) * 0.9; }
    if (a.y - a.r > H + 40) {
      if (dying <= 0) damagePerimeter(a);
      killAsteroid(i);
      continue;
    }
    if (player.alive && player.inv <= 0 && dying <= 0) {
      const dx = a.x - player.x, dy = a.y - player.y, rr = a.r * 0.8 + 13;
      if (dx * dx + dy * dy < rr * rr) {
        explode(a.x, a.y, a.size);
        killAsteroid(i);
        damagePlayer(a.size === 3 ? 26 : a.size === 2 ? 18 : 12, player.x, player.y - 8);
        continue;
      }
    }
  }
}

function ambient(dt) {
  if (state === S.MENU) {
    ambientTimer -= dt;
    if (ambientTimer <= 0 && asteroids.length < 6) {
      ambientTimer = rand(1.4, 2.8);
      const a = spawnAsteroid(3, rand(30, Math.max(70, W - 30)), -70, rand(-24, 24), rand(26, 52));
      if (a) a.ambient = true;
    }
  }
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx * dt; a.y += a.vy * dt; a.rot += a.vr * dt;
    if (a.x < -80) a.x = W + 80;
    else if (a.x > W + 80) a.x = -80;
    if (a.y - a.r > H + 70) {
      if (state === S.MENU) {
        a.x = rand(30, Math.max(70, W - 30));
        a.y = -70;
        a.vx = rand(-24, 24); a.vy = rand(26, 52);
      } else {
        killAsteroid(i);
      }
    }
  }
}

function step(dt) {
  tGlobal += dt;
  updateStars(dt);
  if (ann.t < ann.dur) ann.t += dt;
  flashRed = Math.max(0, flashRed - dt * 1.6);
  flashWhite = Math.max(0, flashWhite - dt * 2.0);
  if (shake > 0) { shake *= Math.exp(-5.5 * dt); if (shake < 0.05) shake = 0; }
  if (state === S.PLAYING) simPlaying(dt);
  else ambient(dt);
  updateParticles(dt);
  updatePopups(dt);
  syncHUD();
}

/* ================================================================
   RENDER
================================================================ */
function drawPlayer() {
  const p = player;
  const blink = p.inv > 0 && Math.sin(tGlobal * 26) > 0;
  const alpha = blink ? 0.35 : 1;
  const fl = (state === S.PAUSED) ? 1 : 0.75 + Math.random() * 0.55;
  ctx.save();
  ctx.translate(p.x, p.y);
  /* engine flame (additive) */
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = alpha * 0.95;
  ctx.save();
  ctx.translate(0, 12);
  ctx.scale(1, fl * 1.7);
  ctx.drawImage(GLOW.cyan, -7, -7, 14, 14);
  ctx.restore();
  /* hull */
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = alpha;
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.moveTo(0, -19);
  ctx.lineTo(5, -8);
  ctx.lineTo(15, 10);
  ctx.lineTo(8, 5);
  ctx.lineTo(4, 12);
  ctx.lineTo(0, 7);
  ctx.lineTo(-4, 12);
  ctx.lineTo(-8, 5);
  ctx.lineTo(-15, 10);
  ctx.lineTo(-5, -8);
  ctx.closePath();
  ctx.fill();
  ctx.lineWidth = 1.4;
  ctx.strokeStyle = strokeGrad;
  ctx.stroke();
  ctx.fillStyle = 'rgba(34,211,238,0.95)';
  ctx.beginPath();
  ctx.arc(0, -4, 2.1, 0, TAU);
  ctx.fill();
  /* shield ring */
  const ringA = 0.07 + (p.inv > 0 ? 0.22 * (0.5 + 0.5 * Math.sin(tGlobal * 30)) : 0) + flashRed * 0.25;
  ctx.globalAlpha = Math.min(1, ringA);
  ctx.lineWidth = 1.2;
  ctx.strokeStyle = p.inv > 0 ? 'rgba(255,84,112,0.9)' : 'rgba(124,140,255,0.8)';
  ctx.beginPath();
  ctx.arc(0, 0, 24, 0, TAU);
  ctx.stroke();
  ctx.restore();
  ctx.globalAlpha = 1;
}

function drawAnnounce() {
  const aIn = clamp(ann.t / 0.18, 0, 1);
  const aOut = clamp((ann.dur - ann.t) / 0.5, 0, 1);
  const a = Math.min(aIn, aOut);
  if (a <= 0) return;
  const y = H * 0.3 - ann.t * 6;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  try { ctx.letterSpacing = '0.22em'; } catch (e) {}
  ctx.globalAlpha = a;
  ctx.fillStyle = '#f5f6f8';
  ctx.font = '800 ' + Math.round(clamp(H * 0.048, 22, 36)) + 'px ' + SANS;
  ctx.fillText(ann.text, W / 2, y);
  ctx.fillStyle = 'rgba(139,139,150,0.95)';
  ctx.font = '600 11px ' + MONO;
  ctx.fillText(ann.sub, W / 2, y + 24);
  try { ctx.letterSpacing = '0em'; } catch (e) {}
  ctx.globalAlpha = 1;
}

function render() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = '#08080a';
  ctx.fillRect(0, 0, W, H);

  const sh = (state !== S.PAUSED && shake > 0.05) ? shake : 0;
  if (sh > 0) ctx.translate((Math.random() * 2 - 1) * sh, (Math.random() * 2 - 1) * sh);

  if (gridPattern) {
    ctx.fillStyle = gridPattern;
    ctx.fillRect(-30, -30, W + 60, H + 60);
  }
  /* starfield */
  ctx.fillStyle = '#dfe6ff';
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i];
    ctx.globalAlpha = s.base * (0.72 + 0.28 * Math.sin(tGlobal * s.tw + s.ph));
    ctx.fillRect(s.x, s.y, s.s, s.s);
  }
  ctx.globalAlpha = 1;

  /* asteroids */
  for (let i = 0; i < asteroids.length; i++) {
    const a = asteroids[i];
    ctx.save();
    ctx.translate(a.x, a.y);
    ctx.rotate(a.rot);
    ctx.drawImage(a.img, -a.imgS / 2, -a.imgS / 2, a.imgS, a.imgS);
    ctx.restore();
  }

  /* additive pass: bullets + particles */
  ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < BUL_MAX; i++) {
    const b = B[i];
    if (!b.alive) continue;
    ctx.drawImage(bulletSpr, b.x - 9, b.y - 9, 18, 18);
  }
  for (let i = 0; i < P_MAX; i++) {
    const p = P[i];
    if (p.life <= 0) continue;
    const k = p.life / p.max;
    ctx.globalAlpha = k;
    const s = p.sz * 2.6 * (0.45 + 0.55 * k);
    ctx.drawImage(p.spr, p.x - s / 2, p.y - s / 2, s, s);
  }
  ctx.globalAlpha = 1;

  if (player.alive && (state === S.PLAYING || state === S.PAUSED)) drawPlayer();
  ctx.globalCompositeOperation = 'source-over';

  /* score popups */
  ctx.font = '700 12px ' + MONO;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (let i = 0; i < TXT.length; i++) {
    const t = TXT[i];
    if (t.t >= t.life) continue;
    ctx.globalAlpha = 1 - t.t / t.life;
    ctx.fillStyle = t.color;
    ctx.fillText(t.str, t.x, t.y);
  }
  ctx.globalAlpha = 1;

  /* post layer (unshaken) */
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  if (vignette) ctx.drawImage(vignette, 0, 0, W, H);
  if (flashRed > 0.01) {
    ctx.fillStyle = 'rgba(255,64,96,' + (flashRed * 0.16).toFixed(3) + ')';
    ctx.fillRect(0, 0, W, H);
  }
  if (flashWhite > 0.01) {
    ctx.fillStyle = 'rgba(240,244,255,' + flashWhite.toFixed(3) + ')';
    ctx.fillRect(0, 0, W, H);
  }
  if (ann.t < ann.dur) drawAnnounce();
}

/* ================================================================
   MAIN LOOP — fixed timestep accumulator
================================================================ */
function frame(now) {
  requestAnimationFrame(frame);
  let d = now - last;
  last = now;
  if (d > 250) d = 250;
  if (d < 0) d = 0;
  if (state !== S.PAUSED) {
    acc += d * (dying > 0 ? 0.3 : 1);   // slow-motion dilates accumulated time
    if (acc > 240) acc = 240;
    while (acc >= STEP) {
      step(1 / 60);
      acc -= STEP;
    }
  }
  render();
}

/* ================================================================
   STATE MACHINE & HUD
================================================================ */
const hudCache = { s: -1, w: -1, sh: -1, m: -1 };
function syncHUD() {
  if (hudCache.s !== score) { hudCache.s = score; elScore.textContent = fmt(score); }
  if (hudCache.w !== wave) { hudCache.w = wave; elWave.textContent = wave; }
  if (hudCache.sh !== shield) {
    hudCache.sh = shield;
    elShield.style.width = shield + '%';
    elShield.classList.toggle('low', shield < 30);
  }
  if (hudCache.m !== mult) {
    hudCache.m = mult;
    elCombo.textContent = '×' + mult;
    elCombo.classList.toggle('on', mult > 1);
  }
}

function setState(s) {
  state = s;
  document.body.dataset.state = STATE_NAMES[s];
  ovMenu.classList.toggle('hidden', s !== S.MENU);
  ovPause.classList.toggle('hidden', s !== S.PAUSED);
  ovOver.classList.toggle('hidden', s !== S.OVER);
  if (s === S.MENU) elMenuBest.textContent = fmt(best);
  if (s === S.PLAYING) Music.start(); else Music.stop();
}

function startGame() {
  A.init();
  asteroids.length = 0;
  for (let i = 0; i < BUL_MAX; i++) B[i].alive = false;
  for (let i = 0; i < P_MAX; i++) P[i].life = 0;
  for (let i = 0; i < TXT.length; i++) TXT[i].t = TXT[i].life;
  score = 0; wave = 1; waveTimer = 0; shield = 100;
  combo = 0; comboT = 0; mult = 1;
  shake = 0; flashRed = 0; flashWhite = 0; dying = 0;
  spawnTimer = 1.0; elapsed = 0; fireCd = 0; engineAcc = 0;
  newRecord = false;
  player.alive = true; player.inv = 0; player.vx = 0;
  player.x = W / 2;
  player.y = H - Math.max(64, Math.min(100, H * 0.13));
  acc = 0;
  announce('WAVE 1', 'DEFEND THE PERIMETER');
  setState(S.PLAYING);
  syncHUD();
}

function toMenu() {
  asteroids.length = 0;
  for (let i = 0; i < BUL_MAX; i++) B[i].alive = false;
  for (let i = 0; i < P_MAX; i++) P[i].life = 0;
  score = 0; shield = 100; wave = 1; dying = 0;
  shake = 0; flashRed = 0; flashWhite = 0;
  player.alive = true; player.x = W / 2;
  ann.t = 1; ann.dur = 0;
  setState(S.MENU);
  syncHUD();
}

function gameOver() {
  dying = 0;
  overAt = performance.now();
  if (score > best) {
    best = score;
    newRecord = true;
    try { localStorage.setItem('adc_best', String(best)); } catch (e) {}
  }
  elFinalScore.textContent = fmt(score);
  elFinalWave.textContent = wave;
  elFinalBest.textContent = fmt(best);
  elBadge.classList.toggle('hidden', !newRecord);
  SFX.gameOver();
  setState(S.OVER);
  if (newRecord) setTimeout(() => SFX.record(), 700);
}

function togglePause() {
  if (state === S.PLAYING) {
    setState(S.PAUSED);
  } else if (state === S.PAUSED) {
    setState(S.PLAYING);
    last = performance.now();
    acc = 0;
  }
}

function toggleMute() {
  A.init();
  A.setMuted(!muted);
  btnMute.classList.toggle('muted', muted);
  SFX.click();
}

/* ================================================================
   INPUT — keyboard + unified pointer (mouse / touch / pen)
================================================================ */
window.addEventListener('keydown', (e) => {
  const c = e.code;
  if (c === 'ArrowLeft' || c === 'KeyA') { keys.left = true; e.preventDefault(); return; }
  if (c === 'ArrowRight' || c === 'KeyD') { keys.right = true; e.preventDefault(); return; }
  if (c === 'Space' || c === 'KeyW' || c === 'ArrowUp') {
    e.preventDefault();
    if (!e.repeat) {
      if (state === S.MENU) startGame();
      else if (state === S.OVER && performance.now() - overAt > 500) startGame();
    }
    keys.fire = true;
    return;
  }
  if (c === 'Enter') {
    if (state === S.MENU) startGame();
    else if (state === S.OVER && performance.now() - overAt > 500) startGame();
    return;
  }
  if (c === 'KeyP' || c === 'Escape') {
    if (state === S.PLAYING || state === S.PAUSED) togglePause();
    return;
  }
  if (c === 'KeyM') { toggleMute(); return; }
});
window.addEventListener('keyup', (e) => {
  const c = e.code;
  if (c === 'ArrowLeft' || c === 'KeyA') keys.left = false;
  else if (c === 'ArrowRight' || c === 'KeyD') keys.right = false;
  else if (c === 'Space' || c === 'KeyW' || c === 'ArrowUp') keys.fire = false;
});

canvas.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  A.init();
  pointerDown = true;
  pointerX = e.clientX;
  try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
});
canvas.addEventListener('pointermove', (e) => { if (pointerDown) pointerX = e.clientX; });
const endPointer = () => { pointerDown = false; };
canvas.addEventListener('pointerup', endPointer);
canvas.addEventListener('pointercancel', endPointer);
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

/* audio unlock on any first gesture (iOS/Safari requirement) */
window.addEventListener('pointerdown', () => { A.init(); }, { passive: true, capture: true });
window.addEventListener('keydown', () => { A.init(); }, { passive: true, capture: true });

/* auto-pause when tab hidden */
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state === S.PLAYING) togglePause();
});

/* buttons */
btnStart.addEventListener('click', () => { SFX.click(); startGame(); });
btnRetry.addEventListener('click', () => { SFX.click(); startGame(); });
btnResume.addEventListener('click', () => { SFX.click(); togglePause(); });
btnQuit.addEventListener('click', () => { SFX.click(); toMenu(); });
btnMenu2.addEventListener('click', () => { SFX.click(); toMenu(); });
btnPause.addEventListener('click', () => {
  if (state === S.PLAYING || state === S.PAUSED) { SFX.click(); togglePause(); }
});
btnMute.addEventListener('click', toggleMute);

/* ================================================================
   RESIZE (high-DPI aware, rAF-debounced)
================================================================ */
function resize() {
  dpr = clamp(window.devicePixelRatio || 1, 1, 2.5);
  W = Math.max(1, window.innerWidth);
  H = Math.max(1, window.innerHeight);
  canvas.width = Math.round(W * dpr);
  canvas.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  rebuildGrid();
  rebuildVignette();
  rebuildStars();
  player.y = H - Math.max(64, Math.min(100, H * 0.13));
  player.x = clamp(player.x || W / 2, 20, W - 20);
}
let resizeQueued = false;
function onResize() {
  if (resizeQueued) return;
  resizeQueued = true;
  requestAnimationFrame(() => { resizeQueued = false; resize(); });
}
window.addEventListener('resize', onResize);
window.addEventListener('orientationchange', onResize);

/* ================================================================
   BOOT
================================================================ */
function boot() {
  buildShipGrads();
  resize();
  player.x = W / 2;
  player.y = H - Math.max(64, Math.min(100, H * 0.13));
  /* ambient backdrop rocks for the menu */
  for (let i = 0; i < 4; i++) {
    const a = spawnAsteroid(3, rand(40, Math.max(80, W - 40)), rand(-40, H - 60), rand(-22, 22), rand(26, 50));
    if (a) a.ambient = true;
  }
  let coarse = false;
  try { coarse = window.matchMedia('(pointer: coarse)').matches; } catch (e) {}
  if (coarse) elHint.textContent = 'DRAG TO STEER · HOLD TO FIRE';
  setState(S.MENU);
  syncHUD();
  last = performance.now();
  requestAnimationFrame(frame);
}
boot();

})();
</script>
</body>
</html>
